package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	const M = 1_000_000_007
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	buf := make([]byte, 1<<16)
	first := true
	// c: number of expressions, f: sum of their values, g: sum of their last-segment values.
	var c, f, g uint64
	for {
		k, err := reader.Read(buf)
		for _, ch := range buf[:k] {
			if ch < '0' || ch > '9' {
				continue
			}
			d := uint64(ch - '0')
			if first {
				c, f, g, first = 1, d, d, false
				continue
			}
			cd := c * d % M
			f = (2*f + 9*g + 2*cd) % M
			g = (10*g + 2*cd) % M
			c = c * 2 % M
		}
		if err != nil {
			break
		}
	}
	fmt.Println(f)
}
